            this.status = status;
            this.body = body;
        }

        public int status() { return status; }
        public T body() { return body; }
    }

    public static Reply<Map<String, Integer>> channelCount(Directory directory,
                                                            long id) {
        Objects.requireNonNull(directory, "directory");
        Profile profile = directory.find(id);
        if (profile == null) return new Reply<>(204, null);

        Map<String, Integer> body = new LinkedHashMap<>();
        body.put("channelCount", profile.channels().size());
        return new Reply<>(200, Collections.unmodifiableMap(body));
    }

    public static Reply<List<String>> channels(Directory directory, long id) {
