import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;

public class SolutionTest {
    public static void main(String[] args) {
        List<String> source = new ArrayList<String>(Arrays.asList("email", "sms", "email"));
        Solution.Profile profile = new Solution.Profile(" user ", source);
        assertEquals("user", profile.handle());
        assertEquals(Arrays.asList("email", "sms", "email"), profile.channels());
        source.clear();
        assertEquals(Arrays.asList("email", "sms", "email"), profile.channels());
        expectUnsupported(new Runnable() {
            public void run() { profile.channels().add("push"); }
        });

        Solution.Profile noChannels = new Solution.Profile("empty", null);
        assertTrue(noChannels.channels().isEmpty(), "null channels should become empty");
        expectIllegalArgument(new Runnable() {
            public void run() { new Solution.Profile(null, Collections.<String>emptyList()); }
        });
        expectIllegalArgument(new Runnable() {
            public void run() { new Solution.Profile("  ", Collections.<String>emptyList()); }
        });
        expectNullPointer(new Runnable() {
            public void run() { new Solution.Profile("ok", Arrays.asList("x", null)); }
        });

        Solution.Directory found = new Solution.Directory() {
            public Solution.Profile find(long id) { return profile; }
        };
        Solution.Reply<Map<String, Integer>> count = Solution.channelCount(found, 9L);
        assertEquals(200, count.status());
        assertEquals(1, count.body().size());
        assertEquals(Integer.valueOf(3), count.body().get("channelCount"));
        assertTrue(count.body().containsKey("channelCount"), "required count key missing");

        Solution.Reply<List<String>> channels = Solution.channels(found, 9L);
        assertEquals(200, channels.status());
        assertEquals(Arrays.asList("email", "sms", "email"), channels.body());
        expectUnsupported(new Runnable() {
            public void run() { channels.body().clear(); }
        });

        Solution.Directory missing = new Solution.Directory() {
            public Solution.Profile find(long id) { return null; }
        };
        Solution.Reply<Map<String, Integer>> noCount = Solution.channelCount(missing, 1L);
        assertEquals(204, noCount.status());
        assertEquals(null, noCount.body());
        Solution.Reply<List<String>> noList = Solution.channels(missing, 1L);
        assertEquals(404, noList.status());
        assertTrue(noList.body() != null && noList.body().isEmpty(), "404 body must be empty");
        expectUnsupported(new Runnable() {
            public void run() { noList.body().add("x"); }
        });

        expectNullPointer(new Runnable() {
            public void run() { Solution.channelCount(null, 1L); }
        });
        expectNullPointer(new Runnable() {
            public void run() { Solution.channels(null, 1L); }
        });

        final RuntimeException failure = new RuntimeException("directory failure");
        Solution.Directory throwing = new Solution.Directory() {
            public Solution.Profile find(long id) { throw failure; }
        };
        assertSameThrown(failure, new Runnable() {
            public void run() { Solution.channelCount(throwing, 1L); }
        });
        assertSameThrown(failure, new Runnable() {
            public void run() { Solution.channels(throwing, 1L); }
        });
    }

    private static void assertSameThrown(RuntimeException expected, Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected exception");
        } catch (RuntimeException actual) {
            if (actual != expected) throw new AssertionError("exception was not propagated unchanged");
        }
    }

    private static void expectIllegalArgument(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void expectNullPointer(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected NullPointerException");
        } catch (NullPointerException expected) {
        }
    }

    private static void expectUnsupported(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void assertEquals(Object expected, Object actual) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError("expected " + expected + " but got " + actual);
        }
    }
}

